export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
  let calls = 0;
  let windowStart = 0;

  return function () {
    const now = Date.now();
    const windowStart = now - windowMs;

    if (calls >= maxPerWindow) {
      return;
    }

    calls += 1;
    fn();
  };
}

// Self-test
const originalFn = () => {
  console.log("fn called");
};

const throttled = throttle(originalFn, 5, 60_000);

// Simulate 6 calls
const start = Date.now();
for (let i = 0; i < 6; i++) {
  throttled();
}
const end = Date.now();
console.log(`Throttled calls took ${end - start}ms`);

if (originalFn.callCount === 5) {
  console.log("self-test passed");
} else {
  process.exit(1);
}

